const css="\n/* Karunvaya Foundation · Volunteer application detail modal v1 */\n.kv-va-modal{--kv-navy:#10294f;--kv-gold:#b38a46;--kv-ink:#203a5b;--kv-muted:#586b86;--kv-line:#d8e3f0;font-family:Inter,\"Segoe UI\",Arial,sans-serif!important;color:var(--kv-ink)!important;background:#f7f9fc!important;border-radius:16px!important;box-shadow:0 20px 70px rgba(16,41,79,.2)!important}\n.kv-va-modal .kv-va-modal-title{font-family:Georgia,\"Times New Roman\",serif!important;font-size:clamp(23px,2.5vw,30px)!important;font-weight:600!important;letter-spacing:-.02em!important;line-height:1.25!important;color:var(--kv-navy)!important}\n.kv-va-modal .kv-va-modal-header{background:#fff!important;border-bottom:1px solid var(--kv-line)!important}\n.kv-va-modal .kv-va-section{background:#fff!important;border:1px solid var(--kv-line)!important;border-radius:13px!important;overflow:hidden!important;box-shadow:0 3px 14px rgba(16,41,79,.045)!important;margin-bottom:16px!important}\n.kv-va-modal .kv-va-section-header{background:var(--kv-navy)!important;border-bottom:0!important;border-left:4px solid var(--kv-gold)!important;padding:13px 17px!important;min-height:40px!important;box-sizing:border-box!important}\n.kv-va-modal .kv-va-section-heading{font-family:Inter,\"Segoe UI\",Arial,sans-serif!important;color:#fff!important;font-size:12px!important;font-weight:750!important;letter-spacing:.095em!important;line-height:1.35!important;text-transform:uppercase!important}\n.kv-va-modal .kv-va-label{font-family:Inter,\"Segoe UI\",Arial,sans-serif!important;color:#526986!important;font-size:12px!important;font-weight:650!important;letter-spacing:.012em!important;line-height:1.5!important}\n.kv-va-modal .kv-va-value{font-family:Inter,\"Segoe UI\",Arial,sans-serif!important;color:var(--kv-navy)!important;font-size:14px!important;font-weight:550!important;line-height:1.65!important;overflow-wrap:anywhere!important}\n.kv-va-modal .kv-va-field{min-width:0}\n.kv-va-modal .kv-va-long-content{background:#f6f9fd!important;border:1px solid #e3ebf4!important;border-radius:10px!important;padding:13px 16px!important;margin-top:7px!important;font-family:Inter,\"Segoe UI\",Arial,sans-serif!important;font-size:14px!important;font-weight:400!important;line-height:1.85!important;color:#284261!important;white-space:pre-line!important;overflow-wrap:break-word!important}\n.kv-va-modal .kv-va-long-content p{font-size:14px!important;line-height:1.85!important;color:#284261!important;margin:0 0 13px!important}\n.kv-va-modal .kv-va-long-content p:last-child{margin-bottom:0!important}\n.kv-va-modal .kv-va-close{font:600 13px/1.3 Inter,\"Segoe UI\",Arial,sans-serif!important;background:#fff!important;border:1px solid #cbd8e7!important;color:var(--kv-navy)!important;border-radius:9px!important;padding:10px 15px!important;transition:background .15s,border-color .15s!important}\n.kv-va-modal .kv-va-close:hover{background:#edf3fa!important;border-color:var(--kv-gold)!important}\n@media(max-width:640px){.kv-va-modal .kv-va-modal-title{font-size:23px!important}.kv-va-modal .kv-va-section-header{padding:12px 13px!important}.kv-va-modal .kv-va-long-content{padding:12px!important;font-size:13.5px!important}}\n@media(prefers-reduced-motion:reduce){.kv-va-modal .kv-va-close{transition:none!important}}\n\n/* Karunvaya Admin dashboard: accessible navy & gold interface, v2 */\nbody.kv-admin-theme{\n --kv-admin-navy:#10294f;--kv-admin-gold:#b38a46;\n --kv-admin-ink:#203a5b;--kv-admin-muted:#516680;\n --kv-admin-line:#d8e3f0;--kv-admin-canvas:#f4f7fb;\n color:var(--kv-admin-ink);font-family:Inter,\"Segoe UI\",Arial,sans-serif;\n -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;\n}\nbody.kv-admin-theme .kv-admin-scope{color:var(--kv-admin-ink);font-family:Inter,\"Segoe UI\",Arial,sans-serif;}\nbody.kv-admin-theme .kv-admin-heading{\n font-family:Georgia,\"Times New Roman\",serif!important;\n color:var(--kv-admin-navy)!important;letter-spacing:-.025em!important;\n line-height:1.24!important;font-size:clamp(24px,2.25vw,31px)!important;\n font-weight:600!important;\n}\nbody.kv-admin-theme .kv-admin-subheading{\n color:var(--kv-admin-navy)!important;font-family:Inter,\"Segoe UI\",Arial,sans-serif!important;\n font-size:17px!important;font-weight:700!important;line-height:1.4!important;\n letter-spacing:-.01em!important;\n}\nbody.kv-admin-theme .kv-admin-panel{\n border:1px solid var(--kv-admin-line)!important;border-radius:14px!important;\n background:#fff!important;box-shadow:0 4px 16px rgba(16,41,79,.045)!important;\n}\nbody.kv-admin-theme .kv-admin-stat{\n border:1px solid var(--kv-admin-line)!important;border-top:3px solid var(--kv-admin-gold)!important;\n border-radius:12px!important;background:#fff!important;\n box-shadow:0 3px 12px rgba(16,41,79,.05)!important;\n}\nbody.kv-admin-theme .kv-admin-stat :is(.value,.number,[class*=\"count\"],[class*=\"value\"]){\n color:var(--kv-admin-navy)!important;font-weight:750!important;\n font-variant-numeric:tabular-nums;\n}\nbody.kv-admin-theme .kv-admin-table{\n border-collapse:separate!important;border-spacing:0!important;\n width:100%;font:400 13.5px/1.6 Inter,\"Segoe UI\",Arial,sans-serif!important;\n color:var(--kv-admin-ink)!important;\n}\nbody.kv-admin-theme .kv-admin-table thead th{\n color:var(--kv-admin-navy)!important;background:#eaf0f7!important;\n border-bottom:2px solid #cddbeb!important;\n font-size:12px!important;font-weight:750!important;\n letter-spacing:.03em!important;text-align:left!important;\n white-space:nowrap;padding:12px 14px!important;\n}\nbody.kv-admin-theme .kv-admin-table tbody td{\n color:#27405f!important;padding:13px 14px!important;\n border-bottom:1px solid #e8edf4!important;\n vertical-align:middle!important;overflow-wrap:anywhere!important;\n}\nbody.kv-admin-theme .kv-admin-table tbody tr:nth-child(even){background:#f8fafd!important;}\nbody.kv-admin-theme .kv-admin-table tbody tr:hover{background:#eff4fa!important;}\nbody.kv-admin-theme .kv-admin-table tbody tr:last-child td{border-bottom-color:transparent!important;}\nbody.kv-admin-theme .kv-admin-field{\n background:#fff!important;color:var(--kv-admin-navy)!important;\n border:1px solid #c8d5e5!important;border-radius:9px!important;\n font:500 14px/1.4 Inter,\"Segoe UI\",Arial,sans-serif!important;\n min-height:39px;\n}\nbody.kv-admin-theme .kv-admin-field::placeholder{color:#697b91!important;opacity:1;}\nbody.kv-admin-theme .kv-admin-field:focus-visible{\n outline:2px solid var(--kv-admin-gold)!important;outline-offset:2px!important;\n border-color:var(--kv-admin-gold)!important;\n}\nbody.kv-admin-theme .kv-admin-action{\n border:1px solid #cbd9e8!important;border-radius:9px!important;\n color:var(--kv-admin-navy)!important;\n font:650 13px/1.35 Inter,\"Segoe UI\",Arial,sans-serif!important;\n letter-spacing:0!important;min-height:36px!important;\n}\nbody.kv-admin-theme .kv-admin-action:hover{\n border-color:var(--kv-admin-gold)!important;\n box-shadow:0 2px 10px rgba(16,41,79,.09)!important;\n}\nbody.kv-admin-theme :is(a,button,input,select,textarea):focus-visible{\n outline:2px solid var(--kv-admin-gold)!important;outline-offset:3px!important;\n}\nbody.kv-admin-theme .kv-admin-sidebar{\n background:var(--kv-admin-navy)!important;color:#f7f9fc!important;\n}\nbody.kv-admin-theme .kv-admin-sidebar :is(a,button){color:#f7f9fc!important;}\nbody.kv-admin-theme .kv-admin-sidebar :is(a,button):hover{background:#23446b!important;}\nbody.kv-admin-theme .kv-admin-sidebar :is(a[aria-current=\"page\"],a.active,[aria-selected=\"true\"]){\n background:#294a70!important;border-left:3px solid var(--kv-admin-gold)!important;\n}\nbody.kv-admin-theme .kv-admin-status{\n display:inline-flex!important;align-items:center!important;\n border-radius:100px!important;padding:4px 10px!important;\n border:1px solid #cfdae8!important;font-weight:700!important;\n font-size:12px!important;line-height:1.4!important;\n}\nbody.kv-admin-theme .kv-admin-status-pending{\n color:#825919!important;background:#fff6e3!important;border-color:#e8d6ae!important;\n}\nbody.kv-admin-theme .kv-admin-status-approved,\nbody.kv-admin-theme .kv-admin-status-active,\nbody.kv-admin-theme .kv-admin-status-completed{\n color:#20664f!important;background:#e9f6f0!important;border-color:#bee4d2!important;\n}\nbody.kv-admin-theme .kv-admin-status-rejected,\nbody.kv-admin-theme .kv-admin-status-failed{\n color:#9d3434!important;background:#fceded!important;border-color:#eac6c6!important;\n}\n/* Volunteer modal refinements also apply when it opens from the admin panel */\nbody.kv-admin-theme .kv-va-modal{\n max-height:min(92vh,960px);\n}\nbody.kv-admin-theme .kv-va-modal .kv-va-section{\n margin-bottom:16px!important;\n}\nbody.kv-admin-theme .kv-va-modal :is(.kv-va-value,.kv-va-long-content){\n user-select:text;\n}\n@media(max-width:680px){\n body.kv-admin-theme .kv-admin-table thead th,\n body.kv-admin-theme .kv-admin-table tbody td{padding:11px 10px!important;}\n body.kv-admin-theme .kv-admin-heading{font-size:24px!important;}\n}\n@media(prefers-reduced-motion:reduce){\n body.kv-admin-theme *,body.kv-admin-theme *::before,body.kv-admin-theme *::after{\n transition:none!important;animation:none!important;\n }\n}\n";
const js="(()=>{\n\"use strict\";\nconst labelNames=[\"Full Name\",\"Email Address\",\"Phone Number\",\"City\",\"Age Group\",\"Area of Interest\",\"Availability\",\"Motivation\",\"Skills & Experience\",\"Application Date\",\"Reference ID\",\"Status\"];\nconst lower=s=>String(s||\"\").trim().replace(/\\s+/g,\" \").toLowerCase();\nfunction leaf(root,text){\n const target=lower(text);\n return Array.from(root.querySelectorAll(\"h1,h2,h3,h4,h5,span,div,strong,b,label,p,small,dt\")).find(el=>el.children.length<=1&&lower(el.textContent)===target);\n}\nfunction findDialog(title){\n const direct=title.closest('[role=\"dialog\"],dialog,.modal-content,.modal-dialog,[class*=\"modal-content\"],[class*=\"modalDialog\"],[class*=\"modal-dialog\"]');\n if(direct&&direct!==document.body)return direct;\n let p=title.parentElement;\n for(let i=0;p&&p!==document.body&&i<8;i++,p=p.parentElement){\n  const t=lower(p.textContent);\n  if(t.includes(\"personal information\")&&t.includes(\"volunteer profile\"))return p;\n }\n return null;\n}\nfunction apply(){\n const title=Array.from(document.querySelectorAll(\"h1,h2,h3,h4,[role=heading],strong,div,span\")).find(e=>e.children.length<=1&&lower(e.textContent)===\"volunteer application details\");\n if(!title)return;\n const root=findDialog(title);if(!root)return;\n root.classList.add(\"kv-va-modal\");\n title.classList.add(\"kv-va-modal-title\");\n const h=title.parentElement;\n if(h&&h!==root&&lower(h.textContent).length<110)h.classList.add(\"kv-va-modal-header\");\n for(const [head,keys] of [[\"PERSONAL INFORMATION\",[\"full name\",\"email address\"]],[\"VOLUNTEER PROFILE\",[\"area of interest\",\"availability\"]],[\"APPLICATION INFORMATION\",[\"status\"]],[\"APPLICATION INFO\",[\"status\"]]]){\n  const el=leaf(root,head);if(!el)continue;el.classList.add(\"kv-va-section-heading\");\n  if(el.parentElement&&el.parentElement!==root&&lower(el.parentElement.textContent).length<110)el.parentElement.classList.add(\"kv-va-section-header\");\n  let p=el.parentElement;\n  for(let i=0;p&&p!==root&&i<5;i++,p=p.parentElement){\n   const s=lower(p.textContent);\n   if(keys.every(k=>s.includes(k))&&!((head===\"PERSONAL INFORMATION\")&&s.includes(\"volunteer profile\"))){\n    p.classList.add(\"kv-va-section\");break;\n   }\n  }\n }\n for(const name of labelNames){\n  const el=leaf(root,name);if(!el)continue;\n  el.classList.add(\"kv-va-label\");\n  const p=el.parentElement;if(!p||p===root)continue;\n  p.classList.add(\"kv-va-field\");\n  let value=el.nextElementSibling;\n  if(!value&&p.children.length===2)value=Array.from(p.children).find(x=>x!==el);\n  if(value){value.classList.add([\"Motivation\",\"Skills & Experience\"].includes(name)?\"kv-va-long-content\":\"kv-va-value\");}\n }\n const close=Array.from(root.querySelectorAll(\"button,[role=button]\")).find(e=>lower(e.textContent).startsWith(\"close\")||lower(e.getAttribute(\"aria-label\"))===\"close\");\n if(close)close.classList.add(\"kv-va-close\");\n}\nlet pending=false;\nconst schedule=()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;apply()})};\nif(document.readyState===\"loading\")document.addEventListener(\"DOMContentLoaded\",schedule,{once:true});else schedule();\nnew MutationObserver(schedule).observe(document.documentElement,{subtree:true,childList:true});\n})();\n;(()=>{\n\"use strict\";\nconst norm=(s)=>String(s||\"\").replace(/\\s+/g,\" \").trim().toLowerCase();\nconst adminPaths=/\\/(?:admin|admin[-_]?dashboard|admin[-_]?panel)(?:\\/|\\.html(?:$|[?#])|$)/i;\nconst headingMatches=/^(admin dashboard|admin panel|volunteer applications|volunteer management|application management|donation management|admin console|manage volunteers|manage applications|admin overview)$/i;\nfunction activate(){\n const titles=Array.from(document.querySelectorAll(\"h1,h2,h3,[role=heading]\"));\n const routeIsAdmin=adminPaths.test(location.pathname);\n const hasAdminHeading=titles.some(e=>headingMatches.test(norm(e.textContent)));\n const hasDetailPopup=titles.some(e=>norm(e.textContent)===\"volunteer application details\");\n if(!routeIsAdmin&&!hasAdminHeading&&!hasDetailPopup)return;\n document.body.classList.add(\"kv-admin-theme\");\n const root=document.querySelector(\"main,[role=main],#admin-dashboard,.admin-main,.dashboard-main,.admin-content\")||document.body;\n root.classList.add(\"kv-admin-scope\");\n for(const el of root.querySelectorAll(\"h1,h2,h3,[role=heading]\")){\n  const text=norm(el.textContent);\n  if(!text||el.closest(\".kv-va-modal\"))continue;\n  if(el.matches(\"h1\")||headingMatches.test(text))el.classList.add(\"kv-admin-heading\");\n  else if(el.matches(\"h2,h3\"))el.classList.add(\"kv-admin-subheading\");\n }\n for(const t of root.querySelectorAll(\"table\"))t.classList.add(\"kv-admin-table\");\n const panelSelector=[\n \".admin-card\",\".dashboard-card\",\".data-card\",\n \".admin-panel\",\".dashboard-panel\",\".section-card\",\n \".table-card\",\".table-panel\"\n ].join(\",\");\n for(const e of root.querySelectorAll(panelSelector))e.classList.add(\"kv-admin-panel\");\n const statSelector=[\n \".stat-card\",\".stats-card\",\".metric-card\",\".summary-card\",\n \".kpi-card\",\".stat-box\",\".metric-box\"\n ].join(\",\");\n for(const e of root.querySelectorAll(statSelector))e.classList.add(\"kv-admin-stat\");\n for(const e of root.querySelectorAll('input:not([type=\"checkbox\"]):not([type=\"radio\"]):not([type=\"hidden\"]),select,textarea')){\n  if(e.closest(\".kv-va-modal\"))continue;\n  e.classList.add(\"kv-admin-field\");\n }\n for(const e of root.querySelectorAll(\"button\")){\n  if(e.closest(\".kv-va-modal\"))continue;\n  if(/^(view|view details|details|filter|apply filter|search|export|download|refresh|open)$/i.test(norm(e.textContent))){\n   e.classList.add(\"kv-admin-action\");\n  }\n }\n for(const e of root.querySelectorAll(\"td span,td div,td strong,td b,.status,.status-badge\")){\n  if(e.children.length||e.closest(\".kv-va-modal\"))continue;\n  const s=norm(e.textContent);\n  if([\"pending\",\"approved\",\"rejected\",\"active\",\"completed\",\"failed\"].includes(s)){\n   e.classList.add(\"kv-admin-status\",\"kv-admin-status-\"+s);\n  }\n }\n for(const e of document.querySelectorAll(\"aside,nav,[id*=sidebar],[class*=sidebar]\")){\n  if(!/(sidebar|side-nav|admin-nav|admin-sidebar)/i.test(String(e.id)+\" \"+String(e.className)))continue;\n  if(e.closest(\".kv-va-modal\")||e.closest(\"header\")||e.closest(\".site-header\"))continue;\n  e.classList.add(\"kv-admin-sidebar\");\n }\n}\nlet raf=0;\nconst schedule=()=>{\n if(raf)return;\n raf=requestAnimationFrame(()=>{raf=0;activate();});\n};\nif(document.readyState===\"loading\")document.addEventListener(\"DOMContentLoaded\",schedule,{once:true});\nelse schedule();\nconst watch=()=>{\n if(!document.body)return;\n new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});\n};\nif(document.readyState===\"loading\")document.addEventListener(\"DOMContentLoaded\",watch,{once:true});\nelse watch();\n})();\n";
const panCss="\n/* Karunvaya donor transparency: high-value PAN verification preview */\n.kv-pan-gate{margin:18px 0 20px;padding:20px;border:1px solid #d4c09b;border-left:5px solid #b38a46;border-radius:12px;background:#fffcf6;color:#10294f;box-shadow:0 5px 16px rgba(16,41,79,.05);font-family:Inter,\"Segoe UI\",Arial,sans-serif}\n.kv-pan-gate[hidden]{display:none!important}\n.kv-pan-head{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:9px;margin-bottom:11px}\n.kv-pan-overline{font-size:11px;font-weight:750;letter-spacing:.1em;color:#8b642b;text-transform:uppercase}\n.kv-pan-badge{border-radius:99px;padding:5px 11px;background:#f6e9cc;color:#72511e;font-size:11px;font-weight:750;letter-spacing:.025em}\n.kv-pan-title{font:600 clamp(20px,2.2vw,25px)/1.3 Georgia,\"Times New Roman\",serif;color:#10294f;letter-spacing:-.015em;margin:4px 0 8px}\n.kv-pan-text,.kv-pan-note{font-size:13px;line-height:1.72;color:#344967;margin:9px 0}\n.kv-pan-label{display:block;font:700 13px/1.5 Inter,\"Segoe UI\",Arial,sans-serif;color:#10294f;margin:17px 0 6px}\n.kv-pan-input{display:block;width:100%;box-sizing:border-box;max-width:360px;min-height:48px;padding:11px 13px;border:1px solid #b9c9db;border-radius:9px;background:#fff;color:#10294f;font:700 15px/1.4 Inter,\"Segoe UI\",Arial,sans-serif;letter-spacing:.12em;text-transform:uppercase}\n.kv-pan-input:focus-visible{outline:2px solid #b38a46;outline-offset:2px}\n.kv-pan-result{margin:8px 0;color:#765622;font-size:12px;line-height:1.6;font-weight:650}\n.kv-pan-separator{height:1px;background:#e5d7bd;margin:15px 0}\n.kv-pan-stop{padding:12px 14px;background:#f2f5fa;border:1px solid #dbe3ef;border-radius:9px;color:#243f62;font-size:13px;line-height:1.7}\n.kv-pan-stop strong{color:#10294f}\n.kv-pan-inline-hint{display:block;font-size:12px;line-height:1.65;color:#775526;margin-top:7px}\n@media(max-width:600px){.kv-pan-gate{padding:15px}.kv-pan-title{font-size:21px}.kv-pan-input{max-width:100%}}\n\n/* Always-visible PAN information card on the live Giving form */\n#kv-pan-gate.kv-pan-gate{display:block!important;visibility:visible!important;opacity:1!important;position:relative!important;max-width:100%!important;box-sizing:border-box!important;margin:22px 0!important}\n#kv-pan-gate .kv-pan-kicker{font-weight:800;letter-spacing:.12em;font-size:11px;color:#8b642b;text-transform:uppercase}\n#kv-pan-gate .kv-pan-title{margin-top:8px}\n#kv-pan-gate .kv-pan-alert{margin-top:12px;padding:13px 15px;border-radius:9px;background:#fff5df;border:1px solid #ebd5aa;color:#63481c;font-size:13px;font-weight:650;line-height:1.7}\n#kv-pan-gate .kv-pan-disabled-action{display:inline-flex;align-items:center;justify-content:center;min-height:42px;margin-top:12px;padding:11px 16px;border:1px solid #c7d3df;border-radius:8px;background:#e8edf3;color:#55687e;font-weight:700;font-size:13px;cursor:not-allowed}\n#kv-pan-gate .kv-pan-input:disabled{background:#f1f4f8!important;color:#6b7d91!important;cursor:not-allowed!important}\n#kv-pan-gate .kv-pan-status{padding:10px 12px;background:#f1f6fc;border-radius:8px;color:#1f3d60;font-weight:700;font-size:13px;line-height:1.6;margin:12px 0}\n\n/* PAN live verification: no fake verified state */\n#kv-pan-gate{border:1px solid #bd9654!important;background:#10294f!important;color:#f6f9ff!important;padding:22px!important;border-radius:12px!important}\n#kv-pan-gate .kv-pan-kicker,#kv-pan-gate .kv-pan-overline{color:#e3c38b!important}\n#kv-pan-gate .kv-pan-title{color:#fff!important;font-family:Georgia,serif!important;font-size:clamp(20px,2vw,26px)!important}\n#kv-pan-gate .kv-pan-text,#kv-pan-gate .kv-pan-note{color:#e5ebf4!important;line-height:1.75!important}\n#kv-pan-gate .kv-pan-label{color:#f6f9ff!important}\n#kv-pan-gate .kv-pan-status{background:#203c61!important;border:1px solid #617a9a!important;color:#fff!important;padding:12px 14px!important;border-radius:8px!important}\n#kv-pan-gate .kv-pan-status[data-verified=\"true\"]{background:#1c654c!important;border-color:#99d1b8!important}\n#kv-pan-gate .kv-pan-alert{background:#243e5f!important;border:1px solid #57708f!important;color:#fff!important}\n#kv-pan-gate .kv-pan-input{background:#fff!important;color:#112d4f!important;letter-spacing:.04em!important;font-weight:550!important;max-width:420px!important}\n#kv-pan-gate .kv-pan-input:disabled{color:#5e6f86!important;background:#e9edf3!important}\n#kv-pan-gate .kv-pan-name-input{text-transform:none!important;letter-spacing:0!important}\n#kv-pan-gate .kv-pan-consent{display:flex;gap:10px;align-items:flex-start;margin:16px 0;font-size:12.5px;line-height:1.75;color:#e5ebf4}\n#kv-pan-gate .kv-pan-consent input{margin-top:5px;accent-color:#b38a46;min-width:16px;min-height:16px}\n#kv-pan-gate .kv-pan-verify{background:#e8c68d;color:#10294f;border:1px solid #e8c68d;border-radius:8px;padding:12px 17px;font:700 13px/1.5 Inter,\"Segoe UI\",sans-serif;cursor:pointer}\n#kv-pan-gate .kv-pan-verify:disabled{background:#a9b4c6;border-color:#a9b4c6;color:#364a65;cursor:not-allowed}\n#kv-pan-gate [hidden]{display:none!important}\n";
const panJs="(()=>{\n'use strict';\nif(window.__kvLivePanInit)return;window.__kvLivePanInit=true;\nconst fmt=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0});\nconst LIMIT=100000;\nfunction init(){\n const form=document.querySelector('#giving-form');\n const amountInput=document.querySelector('#custom-amount');\n const card=document.querySelector('#kv-pan-gate');\n if(!form||!amountInput||!card)return;\n amountInput.max='10000000';\n card.innerHTML='<div class=\"kv-pan-head\"><span class=\"kv-pan-kicker\">VERIFIED DONOR IDENTITY</span><span class=\"kv-pan-badge\">SECURE PAN CHECK</span></div>'+\n '<h3 class=\"kv-pan-title\" id=\"kv-pan-title\">PAN verification for donations above ₹1,00,000</h3>'+\n '<p class=\"kv-pan-text\">For high-value contributions, our website requests a real PAN check from an authorised verification provider. The gateway only permits approved donations.</p>'+\n '<div class=\"kv-pan-status\" id=\"kv-pan-status\" role=\"status\" aria-live=\"polite\">Checking verification availability…</div>'+\n '<div id=\"kv-pan-fields\" hidden><p class=\"kv-pan-text\"><strong>Selected amount: <span id=\"kv-pan-amount\">—</span></strong></p>'+\n '<label class=\"kv-pan-label\" for=\"kv-pan-name\">Full name as registered with PAN</label><input id=\"kv-pan-name\" class=\"kv-pan-input kv-pan-name-input\" autocomplete=\"name\" maxlength=\"120\" required disabled>'+\n '<label class=\"kv-pan-label\" for=\"kv-pan-number\">PAN number</label><input id=\"kv-pan-number\" class=\"kv-pan-input\" autocomplete=\"off\" maxlength=\"10\" inputmode=\"text\" placeholder=\"ABCDE1234F\" required disabled>'+\n '<label class=\"kv-pan-consent\"><input type=\"checkbox\" id=\"kv-pan-consent\" disabled><span>I consent to secure verification of my PAN and name through Cashfree Secure ID for this proposed donation. I understand PAN details will be sent to the authorised provider and will not be stored by this website.</span></label>'+\n '<button type=\"button\" class=\"kv-pan-verify\" id=\"kv-pan-verify\" disabled>Verify PAN securely</button></div>'+\n '<p class=\"kv-pan-note\" id=\"kv-pan-privacy\">Real verification requires an approved live provider connection. A valid-looking PAN format is not proof of identity.</p>'+\n '<div class=\"kv-pan-alert\" id=\"kv-pan-payment-note\">High-value online checkout remains restricted until PAN verification and gateway approval are available.</div>';\n const status=card.querySelector('#kv-pan-status'),fields=card.querySelector('#kv-pan-fields'),selected=card.querySelector('#kv-pan-amount');\n const name=card.querySelector('#kv-pan-name'),pan=card.querySelector('#kv-pan-number'),consent=card.querySelector('#kv-pan-consent'),verify=card.querySelector('#kv-pan-verify'),note=card.querySelector('#kv-pan-payment-note');\n let ready=false,busy=false,verification=null;\n const selection=()=>{\n  const custom=amountInput.value.trim();\n  if(custom){const n=Number(custom);return Number.isSafeInteger(n)?n:0;}\n  const choice=form.querySelector('input[name=\"amount\"]:checked');\n  return choice?Number(choice.value):0;\n };\n function reset(){\n  verification=null;status.dataset.verified='false';\n  verify.textContent='Verify PAN securely';\n }\n function update(){\n  const amount=selection();const high=amount>LIMIT;\n  fields.hidden=!high;selected.textContent=fmt.format(amount||0);\n  pan.disabled=!high||!ready||busy;name.disabled=!high||!ready||busy;consent.disabled=!high||!ready||busy;\n  verify.disabled=!high||!ready||busy||!!verification;\n  if(!high){status.textContent='PAN verification becomes required automatically above ₹1,00,000.';note.textContent='Online payments above ₹1 lakh remain subject to verification and gateway approval.';return;}\n  if(!ready){status.textContent='Live PAN verification is not activated. Do not enter PAN details; high-value payments are blocked.';note.textContent='Provider approval and production credentials are required. This is not a test or simulated check.';return;}\n  if(verification){status.textContent='PAN verified by Cashfree Secure ID. Verification reference: '+verification.reference;note.textContent='Identity check passed. High-value checkout still requires payment-gateway approval and activation.';return;}\n  status.textContent='Enter your registered PAN name, PAN number and consent, then press Verify PAN. Verification uses live provider records.';\n  note.textContent='PAN must be verified before high-value payment; gateway approval is a separate requirement.';\n }\n // Always clear verification on change of selected amount or identity.\n for(const el of form.querySelectorAll('input[name=\"amount\"],#custom-amount')){\n  el.addEventListener('change',()=>{reset();update()});\n  el.addEventListener('input',()=>{reset();queueMicrotask(update)});\n }\n for(const el of [name,pan])el.addEventListener('input',reset);\n pan.addEventListener('input',()=>{const v=pan.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,10);if(pan.value!==v)pan.value=v});\n verify.addEventListener('click',async()=>{\n  const amount=selection();const enteredPan=pan.value.trim().toUpperCase();const enteredName=name.value.trim();\n  if(!ready||busy||amount<=LIMIT)return;\n  if(!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(enteredPan)){status.textContent='Enter a PAN in the correct format.';pan.focus();return;}\n  if(enteredName.length<2||enteredName.length>120){status.textContent='Enter your complete name as registered with PAN.';name.focus();return;}\n  if(!consent.checked){status.textContent='Please provide consent for real PAN verification.';consent.focus();return;}\n  busy=true;verify.textContent='Verifying with Cashfree…';update();status.textContent='Contacting the authorised PAN verification provider…';\n  try{\n   const res=await fetch('/api/pan/verify',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'content-type':'application/json'},body:JSON.stringify({amount,pan:enteredPan,name:enteredName,consent:true})});\n   const out=await res.json();\n   if(!res.ok||out.verified!==true||out.mode!=='live')throw Error(out.message||'PAN could not be verified.');\n   verification={reference:String(out.reference||'N/A'),token:out.token||null};\n   pan.value=''; // Never retain raw PAN in the page after verification.\n   name.value='';\n   status.dataset.verified='true';\n  }catch(e){verification=null;status.textContent=e?.message||'Verification unavailable. Payment is blocked.';}\n  finally{busy=false;update();}\n });\n function takeName(){\n  const actualName=form.querySelector('input[name=\"name\"]')?.value?.trim();\n  if(actualName&&!name.value)name.value=actualName;\n }\n const donorName=form.querySelector('input[name=\"name\"]');\n donorName?.addEventListener('change',()=>{if(!verification)takeName()});\n fetch('/api/pan/config',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json()).then(data=>{\n  ready=data.enabled===true&&data.mode==='live';takeName();update();\n }).catch(()=>{ready=false;update()});\n update();\n}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();\n})();";
const panHtml="<section id=\"kv-pan-gate\" class=\"kv-pan-gate\" aria-labelledby=\"kv-pan-title\"><div class=\"kv-pan-head\"><span class=\"kv-pan-kicker\">VERIFIED DONOR IDENTITY</span><span class=\"kv-pan-badge\">PAN CHECK</span></div><h3 class=\"kv-pan-title\" id=\"kv-pan-title\">PAN verification for donations above ₹1,00,000</h3><p class=\"kv-pan-text\">Real verification requires an authorised provider. You cannot enter PAN details or make high-value payments until this service is activated.</p><p class=\"kv-pan-status\" role=\"status\">Checking PAN verification service availability…</p></section>";

const PAN_HIGH_VALUE_THRESHOLD=100000;
function panReply(obj,status=200){
 return new Response(JSON.stringify(obj),{status,headers:{
  'content-type':'application/json; charset=utf-8','cache-control':'no-store',
  'x-content-type-options':'nosniff','referrer-policy':'no-referrer',
  'pragma':'no-cache','content-security-policy':"default-src 'none'"
 }});
}
function panReady(env){return env.PAN_PROVIDER_MODE==='live'&&
 typeof env.CASHFREE_PAN_CLIENT_ID==='string'&&env.CASHFREE_PAN_CLIENT_ID.length>5&&
 typeof env.CASHFREE_PAN_CLIENT_SECRET==='string'&&env.CASHFREE_PAN_CLIENT_SECRET.length>8&&
 typeof env.PAN_TOKEN_SECRET==='string'&&env.PAN_TOKEN_SECRET.length>=32;}
function panNormalize(s){return String(s||'').toUpperCase().replace(/[^A-Z0-9]/g,'');}
function panOriginOK(request){return request.headers.get('origin')===new URL(request.url).origin;}
function panB64(bytes){const b=String.fromCharCode(...bytes);return btoa(b).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'');}
function panUnb64(t){const b=atob(String(t).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(b,c=>c.charCodeAt(0));}
async function panSign(body,secret){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return panB64(new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(body))))}
async function panToken(value,secret){const data=panB64(new TextEncoder().encode(JSON.stringify(value)));return data+'.'+await panSign(data,secret)}
async function panCheckToken(token,amount,name,secret){
 try{
  const [encoded,sig,extra]=String(token||'').split('.');
  if(!encoded||!sig||extra||encoded.length>2048)return false;
  const expected=await panSign(encoded,secret);
  if(sig.length!==expected.length)return false;
  let diff=0;for(let i=0;i<sig.length;i++)diff|=sig.charCodeAt(i)^expected.charCodeAt(i);
  if(diff!==0)return false;
  const data=JSON.parse(new TextDecoder().decode(panUnb64(encoded)));
  return data.v===1&&data.provider==='cashfree-live'&&data.amount===amount&&
   data.name===panNormalize(name)&&Number.isFinite(data.expires)&&data.expires>Date.now()&&data.expires<Date.now()+900000;
 }catch{return false}
}
async function panAuthorizeUser(request,env){
 const uri=new URL('/api/auth/me',request.url);
 const resp=await env.BACKEND.fetch(new Request(uri.href,{method:'GET',headers:{cookie:request.headers.get('cookie')||''}}));
 return resp.ok;
}
async function panApi(request,env){
 const u=new URL(request.url);
 if(u.pathname==='/api/pan/config'){
  if(request.method!=='GET')return panReply({message:'Method not allowed'},405);
  return panReply({enabled:panReady(env),mode:panReady(env)?'live':'unavailable',provider:'cashfree-secure-id',threshold:PAN_HIGH_VALUE_THRESHOLD,
   message:panReady(env)?'Live PAN verification provider is configured. Login is required for high-value verification.':'PAN verification is unavailable until provider approval and production secrets are configured.'});
 }
 if(u.pathname!=='/api/pan/verify'||request.method!=='POST')return panReply({message:'Not found'},404);
 if(!panReady(env))return panReply({verified:false,message:'Official PAN verification is not yet active. No PAN was checked; high-value payments remain blocked.'},503);
 if(!panOriginOK(request))return panReply({verified:false,message:'Invalid origin'},403);
 if(!String(request.headers.get('content-type')||'').toLowerCase().includes('application/json'))return panReply({verified:false,message:'JSON required'},415);
 if((Number(request.headers.get('content-length'))||0)>2300)return panReply({verified:false,message:'Request too large'},413);
 let raw=await request.text();if(raw.length>2300)return panReply({verified:false,message:'Request too large'},413);
 let input;try{input=JSON.parse(raw)}catch{return panReply({verified:false,message:'Invalid request'},400)}
 const amount=Number(input.amount),pan=String(input.pan||'').toUpperCase().trim(),name=String(input.name||'').trim();
 if(!Number.isSafeInteger(amount)||amount<=PAN_HIGH_VALUE_THRESHOLD||amount>10000000)return panReply({verified:false,message:'Select a high-value amount above ₹1,00,000.'},400);
 if(!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(pan)||!name||name.length>120||input.consent!==true)return panReply({verified:false,message:'Valid PAN, registered name and express consent are required.'},400);
 try{if(!await panAuthorizeUser(request,env))return panReply({verified:false,message:'Please log in before PAN verification.'},401)}
 catch{return panReply({verified:false,message:'Account verification is unavailable.'},503)}
 // LIVE ONLY: no sandbox fallback or local format-only success. PAN is never logged or persisted here.
 let res;try{
  res=await fetch('https://api.cashfree.com/verification/pan',{method:'POST',
   headers:{'content-type':'application/json','x-client-id':env.CASHFREE_PAN_CLIENT_ID,'x-client-secret':env.CASHFREE_PAN_CLIENT_SECRET,'x-api-version':'2022-09-13'},
   body:JSON.stringify({pan,name}),cache:'no-store',signal:AbortSignal.timeout(10000)
  });
 }catch{return panReply({verified:false,message:'Live PAN verification service could not be reached. Payment blocked.'},502)}
 if(!res.ok)return panReply({verified:false,message:'PAN verification provider declined the request or is not enabled for this account.'},502);
 let v;try{v=await res.json()}catch{return panReply({verified:false,message:'Provider response was unreadable. Payment blocked.'},502)}
 const nameMatch=String(v.name_match_result||'').toUpperCase();
 const normalizedEqual=panNormalize(v.registered_name)===panNormalize(name);
 const acceptedName=nameMatch==='DIRECT_MATCH'||(normalizedEqual&&String(v.registered_name||'').length>2);
 const verified=v.valid===true&&v.pan_status==='VALID'&&v.pan===pan&&acceptedName&&
  (typeof v.reference_id==='string'||typeof v.reference_id==='number');
 if(!verified)return panReply({verified:false,message:'PAN was not verified with a matching registered name and active status. Payment blocked.'},422);
 const token=await panToken({v:1,provider:'cashfree-live',amount,name:panNormalize(name),reference:String(v.reference_id),expires:Date.now()+10*60*1000},env.PAN_TOKEN_SECRET);
 return panReply({verified:true,mode:'live',reference:String(v.reference_id),token,message:'PAN verified by the live provider. Payment approval is separate.'});
}
async function panOrderGate(request,env){
 if(request.method!=='POST')return env.BACKEND.fetch(request);
 if(!panOriginOK(request))return panReply({error:'Invalid origin'},403);
 let original;try{original=await request.clone().json()}catch{return panReply({error:'Invalid payment request'},400)}
 const amount=Number(original.amount);
 if(!Number.isSafeInteger(amount)||amount<=PAN_HIGH_VALUE_THRESHOLD)return env.BACKEND.fetch(request);
 if(!panReady(env))return panReply({error:'Live PAN verification is unavailable; contributions above ₹1,00,000 are blocked.'},503);
 const donorName=original.donor?.name;
 if(!await panCheckToken(original.panVerificationToken,amount,donorName,env.PAN_TOKEN_SECRET))return panReply({error:'A live verified PAN token bound to this amount and name is required before checkout.'},403);
 if(env.HIGH_VALUE_CHECKOUT_ENABLED!=='true')return panReply({error:'PAN verified, but high-value donations are not enabled until payment-gateway onboarding and approval.'},503);
 return env.BACKEND.fetch(request); // Backend must separately approve >₹1L; never bypass its limit.
}

const festiveCss="/* Karunvaya Foundation — premium festive identity / v1. Scoped to public pages. */\n:root{--kv-luxe-ink:#102a4b;--kv-luxe-midnight:#081c36;--kv-luxe-gold:#d9b674;--kv-luxe-cream:#fcf9f2;--kv-luxe-font:Georgia,\"Times New Roman\",serif}\nbody.kv-luxe-public{--kv-ink:#102a4b;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}\nbody.kv-luxe-public>header,body.kv-luxe-public header{background:rgba(255,254,250,.97)!important;border-bottom:1px solid #e9deca!important;box-shadow:0 10px 24px rgba(12,31,57,.035)}\nbody.kv-luxe-public header nav a,body.kv-luxe-public header nav summary{font-weight:550!important;color:#173651!important;text-decoration:none;transition:color .2s ease}\nbody.kv-luxe-public header nav a:hover,body.kv-luxe-public header nav summary:hover{color:#9c722d!important}\nbody.kv-luxe-public header .header-cta{background:#10294f!important;color:#fff7e8!important;border:1px solid #10294f!important;border-radius:7px!important;box-shadow:0 4px 12px rgba(17,40,72,.12)}\nbody.kv-luxe-public header .header-cta:hover{background:#20456d!important}\nbody.kv-luxe-public :is(.hero .serif,.section-title,.highlight h2){letter-spacing:-.035em}\nbody.kv-luxe-public .hero{background:linear-gradient(132deg,#fffefb,#fcf7ed)!important}\nbody.kv-luxe-public .card{border:1px solid #e5e5e2!important;border-radius:15px!important;overflow:hidden;box-shadow:0 11px 32px rgba(16,41,79,.07);transition:transform .23s ease,box-shadow .23s ease}\nbody.kv-luxe-public .card:hover{transform:translateY(-3px);box-shadow:0 16px 36px rgba(16,41,79,.10)}\nbody.kv-luxe-public :is(a,button):focus-visible{outline:3px solid #bf8d36;outline-offset:3px}\n.kv-luxe-ribbon{display:flex;justify-content:center;align-items:center;gap:12px;min-height:35px;padding:5px 20px;box-sizing:border-box;background:#0c2745;color:#f6e9d0;font:650 11px/1.5 system-ui,-apple-system,\"Segoe UI\",sans-serif;letter-spacing:.12em;text-align:center;text-transform:uppercase;position:relative;z-index:5}\n.kv-luxe-ribbon::before,.kv-luxe-ribbon::after{content:\"✦\";font-size:12px;color:#ddbd7d}\nbody[data-kv-season=\"holi\"] .kv-luxe-ribbon{background:#5c315f}\nbody[data-kv-season=\"eid\"] .kv-luxe-ribbon{background:#174b48}\nbody[data-kv-season=\"national\"] .kv-luxe-ribbon{background:#193e44}\nbody[data-kv-season=\"christmas\"] .kv-luxe-ribbon{background:#193c34}\nbody[data-kv-season=\"harvest\"] .kv-luxe-ribbon{background:#754b23}\n.kv-luxe-main{font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;background:#fbfaf6;padding:38px 0 27px;overflow:hidden;border-bottom:1px solid #ebe5da}\n.kv-luxe-shell{width:min(1320px,calc(100% - 48px));margin:0 auto}\n.kv-luxe-top{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:20px}\n.kv-luxe-kicker{display:block;font-weight:800;font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:#99702c;margin-bottom:8px}\n.kv-luxe-heading{margin:0;color:#0e2b4c;font:400 clamp(24px,2.8vw,38px)/1.12 var(--kv-luxe-font);letter-spacing:-.027em}\n.kv-luxe-heading em{font-style:italic;color:#b08642}\n.kv-luxe-topright{display:flex;align-items:center;gap:10px;padding-bottom:2px}\n.kv-luxe-count{white-space:nowrap;color:#46617a;font-size:12px;font-variant-numeric:tabular-nums;min-width:38px;text-align:center}\n.kv-luxe-arrow,.kv-luxe-play{width:42px;height:42px;display:grid;place-items:center;background:#fff;border:1px solid #cfd9e3;border-radius:50%;color:#102e4d;font-size:19px;line-height:1;cursor:pointer;transition:background .2s,border-color .2s,transform .2s}\n.kv-luxe-play{font-size:13px}\n.kv-luxe-arrow:hover,.kv-luxe-play:hover{background:#f4e8d3;border-color:#bf995f;transform:translateY(-1px)}\n.kv-luxe-track{display:flex;gap:17px;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;scroll-behavior:smooth;scrollbar-width:none;padding:3px 4px 14px;position:relative;overscroll-behavior-x:contain}\n.kv-luxe-track::-webkit-scrollbar{display:none}\n.kv-luxe-slide{position:relative;isolation:isolate;flex:0 0 calc(100% - 168px);min-height:400px;border-radius:19px;overflow:hidden;box-sizing:border-box;scroll-snap-align:start;box-shadow:0 16px 35px rgba(14,30,54,.13);display:flex;align-items:stretch}\n.kv-luxe-slide::before{content:\"\";position:absolute;inset:0;pointer-events:none;z-index:-1}\n.kv-luxe-slide--festival{background:radial-gradient(ellipse at 75% 8%,#9b5e394f,transparent 48%),radial-gradient(ellipse at 28% 95%,#97652a55,transparent 50%),linear-gradient(125deg,#121b37 2%,#351f3c 65%,#672f38 100%);color:#fff9ed}\n.kv-luxe-slide--festival::before{opacity:.4;background:radial-gradient(circle,#e2b765 1px,transparent 2px) 0 0/41px 36px;mask-image:linear-gradient(90deg,transparent 40%,#000)}\n.kv-luxe-slide[data-season=\"holi\"]{background:linear-gradient(120deg,#292551,#793d68 58%,#bb715e)}\n.kv-luxe-slide[data-season=\"eid\"]{background:linear-gradient(120deg,#0a303d,#185049 65%,#2d6958)}\n.kv-luxe-slide[data-season=\"national\"]{background:linear-gradient(120deg,#102c40,#29534f 70%,#756c40)}\n.kv-luxe-slide[data-season=\"christmas\"]{background:linear-gradient(120deg,#0a2834,#1b4d40 70%,#754a39)}\n.kv-luxe-slide[data-season=\"harvest\"]{background:linear-gradient(120deg,#25304a,#69512d 70%,#98693a)}\n.kv-luxe-slide--education{background:#102941;color:#fff6e8}\n.kv-luxe-slide--welfare{background:#223b3b;color:#fff6e8}\n.kv-luxe-body{position:relative;z-index:2;width:54%;box-sizing:border-box;padding:clamp(30px,4.2vw,62px);display:flex;flex-direction:column;justify-content:center;align-items:flex-start}\n.kv-luxe-eyebrow{font-size:11px;font-weight:750;letter-spacing:.20em;color:#e3c183;text-transform:uppercase;line-height:1.55}\n.kv-luxe-line{width:46px;height:2px;background:#d2ab66;margin:18px 0 17px}\n.kv-luxe-title{margin:0;font:400 clamp(30px,4.6vw,59px)/1.07 var(--kv-luxe-font);letter-spacing:-.042em;color:#fffdf5;max-width:710px;text-wrap:balance}\n.kv-luxe-title em{font-weight:400;font-style:italic;color:#eccb8e}\n.kv-luxe-desc{color:#e1e7ef;font:400 clamp(12px,1.18vw,15px)/1.8 system-ui,-apple-system,\"Segoe UI\",sans-serif;max-width:515px;margin:22px 0 22px}\n.kv-luxe-cta{display:inline-flex;align-items:center;justify-content:center;gap:12px;text-decoration:none;color:#142c4a!important;background:#efd6a1;padding:13px 20px;border-radius:7px;font-size:12.5px;font-weight:800;border:1px solid #efd6a1;transition:background .2s,color .2s,transform .2s}\n.kv-luxe-cta:hover{background:#fff1d4;transform:translateY(-1px)}\n.kv-luxe-illustration{position:absolute;right:1%;top:0;bottom:0;width:49%;display:flex;align-items:center;justify-content:center;pointer-events:none}\n.kv-luxe-illustration svg{width:min(94%,400px);max-height:96%;filter:drop-shadow(0 13px 35px #0003)}\n.kv-luxe-image{width:49%;position:absolute;inset:0 0 0 auto;background:#3e5364}\n.kv-luxe-image img{width:100%;height:100%;display:block;object-fit:cover}\n.kv-luxe-image::before{content:\"\";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,#102941 0%,#1029410c 23%,#061a2a11 100%)}\n.kv-luxe-slide--welfare .kv-luxe-image::before{background:linear-gradient(90deg,#223b3b 0%,#223b3b11 26%,transparent 100%)}\n.kv-luxe-image small{position:absolute;z-index:2;bottom:12px;right:16px;font-size:10px;color:white;background:#0b2337c9;border-radius:6px;padding:6px 9px}\n.kv-luxe-slide-tag{position:absolute;right:25px;top:23px;font-size:10px;letter-spacing:.12em;border:1px solid #f0d7a280;border-radius:40px;padding:6px 12px;color:#f4deb7;z-index:2;text-transform:uppercase}\n.kv-luxe-dots{display:flex;justify-content:center;align-items:center;gap:7px;margin:1px 0 17px}\n.kv-luxe-dot{height:9px;width:9px;border:0;border-radius:20px;padding:0;background:#b5bdc6;cursor:pointer;transition:width .2s,background .2s}\n.kv-luxe-dot[aria-current=\"true\"]{width:35px;background:#b18a4f}\n.kv-luxe-footer{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n.kv-luxe-micro{display:flex;align-items:center;gap:14px;min-height:74px;box-sizing:border-box;padding:14px 18px;background:#fff;border:1px solid #e6e4df;border-radius:10px;color:#1a344e!important;text-decoration:none;transition:border-color .18s,box-shadow .18s,transform .18s}\n.kv-luxe-micro:hover{border-color:#be995c;box-shadow:0 8px 25px #152c4512;transform:translateY(-2px)}\n.kv-luxe-micro-icon{height:34px;width:34px;flex:0 0 34px;display:grid;place-items:center;color:#9c733d;font-size:18px;border:1px solid #ebdfcc;background:#fcf9f1;border-radius:9px}\n.kv-luxe-micro strong{display:block;font-size:13px;font-weight:750;color:#1a344e}\n.kv-luxe-micro small{display:block;font-size:11px;color:#677e94;line-height:1.65;margin-top:2px}\n.kv-luxe-micro>span:last-child{margin-left:auto;color:#af8c55}\n@media(max-width:900px){.kv-luxe-slide{flex-basis:calc(100% - 85px);min-height:350px}.kv-luxe-body{width:63%;padding:34px}.kv-luxe-image,.kv-luxe-illustration{width:45%;opacity:.78}.kv-luxe-title{font-size:clamp(29px,5vw,45px)}.kv-luxe-footer{grid-template-columns:repeat(3,1fr)}.kv-luxe-micro{padding:11px;gap:9px}.kv-luxe-micro small{font-size:10px}}\n@media(max-width:650px){.kv-luxe-main{padding:25px 0 22px}.kv-luxe-shell{width:calc(100% - 26px)}.kv-luxe-top{gap:8px;align-items:center}.kv-luxe-heading{font-size:24px}.kv-luxe-topright{gap:5px}.kv-luxe-count{display:none}.kv-luxe-arrow,.kv-luxe-play{height:34px;width:34px;font-size:16px}.kv-luxe-slide{flex-basis:100%;min-height:410px;border-radius:15px}.kv-luxe-body{width:100%;padding:30px 26px 29px;justify-content:flex-end;background:linear-gradient(0deg,#081e35f5 8%,#071c36d7 55%,#071c3640 100%)}.kv-luxe-slide--festival .kv-luxe-body{background:linear-gradient(0deg,#1e203efc 7%,#31213de0 62%,#382a3b66 100%)}.kv-luxe-illustration{width:76%;right:-7%;height:67%;top:-10%;opacity:.42}.kv-luxe-image{width:100%;height:100%;opacity:.67}.kv-luxe-image::before{background:linear-gradient(0deg,#091e35e9,transparent 70%)}.kv-luxe-title{font-size:clamp(32px,9vw,43px)}.kv-luxe-desc{margin:13px 0 18px;font-size:12px;line-height:1.7}.kv-luxe-eyebrow{font-size:10px}.kv-luxe-line{margin:11px 0}.kv-luxe-slide-tag{font-size:9px;right:14px;top:12px}.kv-luxe-footer{grid-template-columns:1fr;gap:8px}.kv-luxe-micro{min-height:65px;padding:9px 14px}.kv-luxe-micro small{font-size:11px}.kv-luxe-ribbon{font-size:9px;letter-spacing:.06em;gap:7px;padding:7px 9px}.kv-luxe-dots{margin-bottom:12px}body.kv-luxe-public .hero{padding-top:46px}}\n@media(prefers-reduced-motion:reduce){.kv-luxe-track{scroll-behavior:auto}.kv-luxe-arrow,.kv-luxe-play,.kv-luxe-cta,.kv-luxe-micro,.kv-luxe-dot,body.kv-luxe-public .card{transition:none!important;transform:none!important}}\n@media print{.kv-luxe-main,.kv-luxe-ribbon{display:none!important}}\n";
